//! Cargo-driven `dinput8.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x753a0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff2d000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff2d000000u64)),
        o => panic!("dinput8-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:dxguid", "engine:uuid", "engine:wine", "import:comctl32", "import:ole32", "import:user32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "x86_64" => &["engine:c:dxguid", "engine:uuid", "engine:wine", "import:comctl32", "import:ole32", "import:user32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "aarch64" => &["engine:c:dxguid", "engine:uuid", "engine:wine", "import:comctl32", "import:ole32", "import:user32", "import:advapi32", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/dinput8",
        "dll/directx/wine/dinput8",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "DIRECTINPUT_VERSION=0x0800",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("dinput8_shims", &["dll/directx/wine/dinput/config.c", "dll/directx/wine/dinput/data_formats.c", "dll/directx/wine/dinput/device.c", "dll/directx/wine/dinput/dinput_main.c", "dll/directx/wine/dinput/effect_linuxinput.c", "dll/directx/wine/dinput/joystick.c", "dll/directx/wine/dinput/joystick_linux.c", "dll/directx/wine/dinput/joystick_linuxinput.c", "dll/directx/wine/dinput/joystick_osx.c", "dll/directx/wine/dinput/keyboard.c", "dll/directx/wine/dinput/mouse.c"])
        .rc("dll/directx/wine/dinput/dinput.rc", rc_includes, rc_flags, rc_defines)
        .rc("dll/directx/wine/dinput8/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/dinput8/dinput8.spec", "dinput8.dll")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
